import{_ as e,o as t,c as r,a2 as i}from"./chunks/framework.CqGS6Fr9.js";const u=JSON.parse('{"title":"Общая планета и поселения","description":"","frontmatter":{"pageId":"players/world","contentRevision":5},"headers":[],"relativePath":"ru/players/world.md","filePath":"ru/players/world.md"}'),l={name:"ru/players/world.md"};function o(n,a,s,d,h,p){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="общая-планета-и-поселения" tabindex="-1">Общая планета и поселения <a class="header-anchor" href="#общая-планета-и-поселения" aria-label="Permalink to &quot;Общая планета и поселения&quot;">​</a></h1><p>Применимость: Rimlink 0.9.2 · RimWorld 1.7 · протокол 1.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><p>Все игроки используют планету сервера. Выбирай свободную клетку при создании колонии. На карте чужие поселения показывают владельца, присутствие, давность посещения, возраст колонии и диапазон богатства, если эти данные доступны.</p><p>Караван и транспортные капсулы предлагают действия на чужом поселении: передача, рейд, визит или live — в зависимости от режима, доступности хозяина и правил сервера. Проверяй подпись действия до подтверждения: визит и реальный рейд не взаимозаменяемы.</p><p>Цветной слой гильдий включается отдельно и не заменяет обычные маркеры карты.</p><h2 id="settlement" tabindex="-1">Как выбрать место и прочитать чужое поселение? <a class="header-anchor" href="#settlement" aria-label="Permalink to &quot;Как выбрать место и прочитать чужое поселение? {#settlement}&quot;">​</a></h2><p>Создание колонии использует уже выбранную сервером планету. Найди свободный tile, проверь биом/рельеф и выбери поселение. Если место заняли одновременно, сервер откажет: выбери другой tile, не пытайся сохранить второе поселение тем же аккаунтом.</p><p>Зелёный индикатор чужого поселения показывает текущий online владельца, серый — offline. Полоса богатства — диапазон 1–5, не точная сумма кошелька. Выбор объекта показывает владельца, фракцию, последнюю активность и возраст колонии. Возраст измеряется игровыми днями, последняя активность — реальным временем.</p><p>Для действия выдели караван и открой правый клик на поселении. Перед подтверждением читай полный пункт: «Передать», «Рейд», «Визит», «Live raid» означают разные риски. Капсулы используют отдельные пункты прибытия. Цвет альянса не заменяет эти правила.</p><h2 id="archive" tabindex="-1">Что происходит после долгого отсутствия? <a class="header-anchor" href="#archive" aria-label="Permalink to &quot;Что происходит после долгого отсутствия? {#archive}&quot;">​</a></h2><p>Сервер может архивировать молодую небогатую колонию после длительного отсутствия (по умолчанию около двух недель, точные условия задаёт администратор). Это не удаление сейва. При входе она возвращается автоматически, если место ещё свободно.</p><p>Если tile занят, не пытайся наложить старую колонию на новое поселение: администратору нужно освобождение места и контролируемое восстановление. Письмо «Пока тебя не было» перечисляет произошедшие серверные события; отсутствие письма может означать отсутствие событий, а не поломку синхронизации.</p><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>По умолчанию одно поселение на игрока. Офлайн-маркер не означает, что карта продолжает симулироваться. Не все действия доступны в мирном режиме.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./visits">Визиты и магазин</a></li><li><a href="./raids-incidents">Рейды и платные события</a></li><li><a href="./guild-influence">Влияние гильдий</a></li></ul>',17)])])}const m=e(l,[["render",o]]);export{u as __pageData,m as default};
